CREATE TABLE instance (singleton boolean PRIMARY KEY DEFAULT TRUE CHECK (singleton), instance_id uuid NOT NULL UNIQUE, reporting_timezone text NOT NULL, page_characters bigint NOT NULL CHECK (page_characters > 0), reset_generation bigint NOT NULL DEFAULT 0 CHECK (reset_generation >= 0));
CREATE TABLE owners (username text PRIMARY KEY, singleton boolean NOT NULL DEFAULT TRUE UNIQUE CHECK (singleton), password_hash text NOT NULL);
CREATE TABLE owner_sessions (token_hash text PRIMARY KEY, username text NOT NULL REFERENCES owners(username) ON DELETE CASCADE, csrf_hash text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE login_failures (username text NOT NULL, ip text NOT NULL, failed_at timestamptz NOT NULL);
CREATE INDEX login_failures_lookup ON login_failures(username, ip, failed_at);
CREATE INDEX login_failures_expiry ON login_failures(failed_at);
CREATE TABLE device (singleton boolean PRIMARY KEY DEFAULT TRUE CHECK (singleton), token_hash text NOT NULL UNIQUE, device_id uuid UNIQUE);
CREATE TABLE books (book_id uuid PRIMARY KEY, title text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE sources (source_id text PRIMARY KEY CHECK (source_id ~ '^[0-9a-f]{64}$'), format text NOT NULL CHECK (format IN ('epub','mobi','pdf')), metadata jsonb NOT NULL, cover bytea, cover_type text, CHECK (cover IS NULL OR octet_length(cover) <= 65536));
CREATE TABLE book_sources (source_id text PRIMARY KEY REFERENCES sources(source_id), book_id uuid NOT NULL REFERENCES books(book_id));
CREATE TABLE annotations (source_id text NOT NULL REFERENCES sources(source_id), annotation_id uuid NOT NULL, version bigint NOT NULL, archived boolean NOT NULL DEFAULT FALSE, content jsonb NOT NULL, PRIMARY KEY (source_id, annotation_id));
CREATE TABLE annotation_versions (source_id text NOT NULL, annotation_id uuid NOT NULL, version bigint NOT NULL, content jsonb NOT NULL, PRIMARY KEY (source_id, annotation_id, version), FOREIGN KEY (source_id, annotation_id) REFERENCES annotations(source_id, annotation_id));
CREATE TABLE packets (device_id uuid NOT NULL, seq bigint NOT NULL, reset_generation bigint NOT NULL, digest text NOT NULL, acknowledgement jsonb NOT NULL, PRIMARY KEY (device_id, seq));
CREATE TABLE events (event_id uuid PRIMARY KEY, device_id uuid NOT NULL, source_id text NOT NULL REFERENCES sources(source_id), reset_generation bigint NOT NULL, digest text NOT NULL, content jsonb NOT NULL);
CREATE TABLE snapshot_versions (device_id uuid NOT NULL, source_id text NOT NULL, section text NOT NULL, reset_generation bigint NOT NULL, version bigint NOT NULL, digest text NOT NULL, PRIMARY KEY (device_id, source_id, section, reset_generation));
CREATE TABLE vocabulary_versions (device_id uuid NOT NULL, reset_generation bigint NOT NULL, version bigint NOT NULL, digest text NOT NULL, PRIMARY KEY (device_id, reset_generation));
CREATE TABLE vocabulary (word_key text PRIMARY KEY, content jsonb NOT NULL);
CREATE TABLE legacy_statistics (source_id text NOT NULL REFERENCES sources(source_id), reporting_date date NOT NULL, native_pages bigint NOT NULL, native_seconds bigint NOT NULL, PRIMARY KEY(source_id, reporting_date));
CREATE TABLE uploads (upload_id uuid PRIMARY KEY, device_id uuid NOT NULL, source_id text, seq bigint NOT NULL, reset_generation bigint NOT NULL, manifest jsonb NOT NULL, expires_at timestamptz NOT NULL, committed_ack jsonb);
CREATE INDEX uploads_device_expiry ON uploads(device_id, expires_at);
CREATE TABLE upload_chunks (upload_id uuid NOT NULL REFERENCES uploads(upload_id) ON DELETE CASCADE, chunk_index integer NOT NULL, digest text NOT NULL, content bytea NOT NULL, PRIMARY KEY(upload_id, chunk_index));
CREATE TABLE goals (year integer PRIMARY KEY CHECK (year BETWEEN 1 AND 9999), target bigint NOT NULL CHECK (target >= 0));
CREATE TABLE reset_tombstones (reset_generation bigint NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, digest text, PRIMARY KEY(reset_generation, entity_type, entity_id));
